import { defineQuery } from 'next-sanity'

/**
 * GROQ queries using projections for performance.
 * These types will be auto-generated by Sanity TypeGen.
 */

// Example: Get all posts with optimized projections
export const POSTS_QUERY = defineQuery(`
  *[_type == "post"] | order(publishedAt desc) {
    _id,
    title,
    slug,
    publishedAt,
    "excerpt": array::join(string::split(pt::text(body), "")[0..255], "") + "...",
    mainImage {
      asset->,
      alt
    },
    author-> {
      name,
      image
    }
  }
`)

// Example: Get single post by slug
export const POST_QUERY = defineQuery(`
  *[_type == "post" && slug.current == $slug][0] {
    _id,
    title,
    slug,
    publishedAt,
    mainImage {
      asset->,
      alt,
      caption
    },
    author-> {
      name,
      image,
      bio
    },
    body,
    "relatedPosts": *[_type == "post" && slug.current != $slug] | order(publishedAt desc) [0...3] {
      _id,
      title,
      slug,
      mainImage {
        asset->,
        alt
      }
    }
  }
`)

// Example: Site settings
export const SETTINGS_QUERY = defineQuery(`
  *[_type == "settings"][0] {
    title,
    description,
    ogImage {
      asset->
    }
  }
`)
